# Apply without removing from the stack
git stash apply stash@{1}

# Move a stash onto its own branch
git stash branch fix/login-crash stash@{0}

# Drop one entry, or all of them
git stash drop stash@{2}
git stash clear

#!/bin/sh
# .git/hooks/pre-commit - refuse commits with unformatted code

cargo fmt --check || {
  echo "run cargo fmt before committing"
  exit 1
}

#!/bin/sh
# .git/hooks/commit-msg - require a conventional prefix

msg=$(head -n 1 "$1")
case "$msg" in
  feat:*|fix:*|docs:*|refactor:*|test:*|chore:*) exit 0 ;;
  *) echo "message must start with feat:, fix:, docs:, refactor:, test: or chore:" ; exit 1 ;;
esac
